'use strict';
const fs=require('fs'),http=require('http'),path=require('path');
const {chromium,webkit}=require('playwright');
const ROOT=path.resolve(__dirname,'../..'),OUTPUT=path.join(ROOT,'artifacts','explanation-integration');
const engines={chromium,webkit},viewports=[320,375,390,430];
const profiles={
  J001:['どういう取引か考える','借方・貸方を決めて仕訳する',false],
  T001:['残高の置き場所を決める','試算表に記入する',true],
  E001:['どこが違うか整理する','訂正仕訳を書く',false],
  L028:['増減と相手勘定を整理する','元帳に転記する',true],
  L029:['数量と単価の動きを整理する','商品有高帳に記入する',true],
  L030:['償却条件を整理する','固定資産台帳に記入する',true],
  L034:['どういう取引か考える','借方・貸方を決めて仕訳帳に記入する',false],
  L035:['記帳する受取手形を選ぶ','受取手形記入帳に記入する',true],
  L036:['記帳する支払手形を選ぶ','支払手形記入帳に記入する',true],
  L039:['増減と相手勘定を整理する','元帳に転記する',true],
  L044:['受入と支払を分ける','現金出納帳に記入する',true],
  L045:['預入と引出を分ける','当座預金出納帳に記入する',true],
  L046:['支払内容を科目に分ける','小口現金出納帳に記入する',true],
  L047:['仕入と返品を分ける','仕入帳に記入する',true],
  L048:['売上と返品を分ける','売上帳に記入する',true],
  L049:['数量と単価の動きを整理する','商品有高帳に記入する',true],
  L050:['現金が増えるか、減るか、動かないかを確認する','使う伝票を決めて記入する',false]
};
const cases=Object.keys(profiles);
const evidence={status:'RUNNING',reports:[],failures:[]},mime={'.css':'text/css','.html':'text/html','.js':'text/javascript'};
const write=()=>{fs.mkdirSync(OUTPUT,{recursive:true});fs.writeFileSync(path.join(OUTPUT,'evidence.json'),JSON.stringify(evidence,null,2)+'\n');};
const server=http.createServer((req,res)=>{const pathname=new URL(req.url,'http://localhost').pathname,relative=pathname==='/'?'.github/visual/explanation-integration.html':pathname.slice(1),file=path.resolve(ROOT,relative);if(!file.startsWith(ROOT+path.sep)||!fs.existsSync(file)||fs.statSync(file).isDirectory()){res.writeHead(404);return res.end('not found');}res.setHeader('content-type',mime[path.extname(file)]||'application/octet-stream');res.end(fs.readFileSync(file));});
async function measure(page,caseId,width){return page.evaluate(({caseId,width})=>{const qs=s=>[...document.querySelectorAll(s)],rect=e=>e.getBoundingClientRect(),sections=qs('.explanation-flow-section'),formulas=qs('.explanation-formula strong');return{caseId,width,headings:sections.map(s=>s.querySelector('h5')?.textContent),sectionCount:sections.length,overflow:document.documentElement.scrollWidth>window.innerWidth+1||document.body.scrollWidth>window.innerWidth+1,formulaTexts:formulas.map(e=>e.textContent),clipped:formulas.filter(e=>e.scrollWidth>e.clientWidth+1||rect(e).right>window.innerWidth+1).map(e=>e.textContent),sourceCards:qs('.explanation-source-card').length,sourceTables:qs('.explanation-source-table').length,sourceTableHeaders:qs('.explanation-source-table th').map(e=>e.textContent),sourceTableRows:qs('.explanation-source-table tbody tr').length,sourceUnknowns:qs('.explanation-source-unknown').length,transferCards:qs('.explanation-transfer-card').length,checks:qs('.explanation-check-item').length,mistakes:qs('.explanation-mistake-card').length,genericSolution:qs('.solution-steps').length,authoredCards:qs('.explanation-card:not(.explanation-takeaway)').length,takeawayCards:qs('.explanation-takeaway').length,takeawayHeading:document.querySelector('.explanation-takeaway h4')?.textContent||'',takeawayItems:qs('.explanation-takeaway li').map(e=>e.textContent),takeawayText:document.querySelector('.explanation-takeaway')?.textContent||'',sourceText:document.querySelector('.explanation-flow-section[data-section="sources"]')?.textContent||'',summaryText:document.querySelector('.explanation-flow-section[data-section="summary"]')?.textContent||'',checkText:document.querySelector('.explanation-flow-section[data-section="checks"]')?.textContent||'',directAmountCalculationCount:formulas.length,bodyCase:document.body.dataset.caseId};},{caseId,width});}
async function run(){await new Promise(r=>server.listen(0,'127.0.0.1',r));const base='http://127.0.0.1:'+server.address().port+'/.github/visual/explanation-integration.html';write();try{for(const[browserName,launcher]of Object.entries(engines)){const browser=await launcher.launch();try{for(const caseId of cases)for(const width of viewports){const page=await browser.newPage({viewport:{width,height:900}}),pageErrors=[];page.on('pageerror',error=>pageErrors.push(String(error?.stack||error?.message||error)));try{await page.goto(base+'?case='+caseId,{waitUntil:'load'});await page.waitForTimeout(25);const m=await measure(page,caseId,width);m.pageErrors=pageErrors;const [summaryHeading,transferHeading,expectsCalculation]=profiles[caseId],expectedHeadings=['まずここを確認',summaryHeading,...(expectsCalculation?['必要な金額を出す']:[]),transferHeading,'最後に確認','間違えやすいところ'];const violations=[];if(m.overflow)violations.push('PAGE_HORIZONTAL_OVERFLOW');if(m.sectionCount!==expectedHeadings.length||JSON.stringify(m.headings)!==JSON.stringify(expectedHeadings))violations.push('SECTION_ORDER');if(m.clipped.length)violations.push('FORMULA_CLIPPED');if(expectsCalculation&&m.directAmountCalculationCount<1)violations.push('CALCULATION_MISSING');if(!expectsCalculation&&m.directAmountCalculationCount!==0)violations.push('UNNECESSARY_CALCULATION');if(m.sourceCards<1||m.transferCards<1||m.checks<1||m.mistakes<1)violations.push('REQUIRED_VISUAL_COMPONENT_MISSING');if(caseId==='T001'&&(m.sourceTables!==1||JSON.stringify(m.sourceTableHeaders)!==JSON.stringify(['勘定科目','借方','貸方'])||m.sourceTableRows!==9))violations.push('TRIAL_BALANCE_SOURCE_TABLE');if(caseId==='T001'&&(!m.formulaTexts.join(' ').includes('410,000 + 175,000 + 60,000 + 289,000 + 90,000 = 1,024,000')||!m.checkText.includes('借方合計と貸方合計が一致しているか確認する')))violations.push('TRIAL_BALANCE_GUIDANCE');if(caseId==='E001'&&(!m.sourceText.includes('帳簿の記録と証ひょうを比べる')||m.transferCards!==2||!m.checkText.includes('訂正する部分だけを直せているか確認する')))violations.push('CORRECTION_GUIDANCE');if(caseId==='J001'&&(!m.summaryText.includes('取引で何が増え、何が減ったか')||!m.checkText.includes('借方合計と貸方合計が合っているか確認する')))violations.push('JOURNAL_GUIDANCE');if(caseId==='L029'&&(m.sourceTables!==1||JSON.stringify(m.sourceTableHeaders)!==JSON.stringify(['日付','摘要','数量','単価（円）','金額（円）'])||m.sourceTableRows!==4||m.sourceUnknowns!==3))violations.push('SOURCE_TABLE_STRUCTURE');if(m.genericSolution!==0)violations.push('GENERIC_SOLUTION_DUPLICATED');if(m.authoredCards!==0)violations.push('LEGACY_AUTHORED_EXPLANATION_DUPLICATED');if(m.takeawayCards!==1||m.takeawayHeading!=='この問題で覚えること'||m.takeawayItems.length<2)violations.push('TAKEAWAY_MISSING');if(/90,000|12,000/u.test(m.takeawayText))violations.push('TAKEAWAY_REPEATS_CASE_ANSWER');if(/\b(?:item|account):/u.test(m.sourceText))violations.push('RAW_INTERNAL_SOURCE_KEY');const learnerMeta=[m.sourceText,m.summaryText,m.checkText,m.takeawayText].join(' ');if(/正答値|資料の項目と数値|記載されている数値|帳簿値|対応づける|条件と整合/u.test(learnerMeta))violations.push('SYSTEM_META_WORDING');if(caseId==='L050'&&!/取引内容と金額を確認する/u.test(m.sourceText))violations.push('VOUCHER_SOURCE_FOCUS_MISSING');if(caseId==='L050'&&!/現金が増えるか、減るか、動かないかを確認して、使う伝票を決めます/u.test(m.summaryText))violations.push('VOUCHER_SUMMARY_MISSING');if(caseId==='L050'&&!/現金の動きに合った伝票を選べているか確認する/u.test(m.checkText))violations.push('VOUCHER_CHECK_MISSING');if(caseId==='L050'&&!/増える → 入金伝票/u.test(m.checkText))violations.push('VOUCHER_MAPPING_MISSING');if(caseId==='L050'&&/現金が増えるか、減るか、動かないかを見る|現金の動きと伝票の種類が合っているか|現金の受取＝入金伝票/u.test(learnerMeta))violations.push('VOUCHER_OLD_WORDING');if(caseId==='L050'&&!/現金が増えるなら入金伝票/u.test(m.takeawayText))violations.push('VOUCHER_TAKEAWAY_MISSING');if(m.bodyCase!==caseId)violations.push('CASE_STATE');if(m.pageErrors.length)violations.push('PAGE_SCRIPT_ERROR');fs.mkdirSync(path.join(OUTPUT,browserName),{recursive:true});await page.screenshot({path:path.join(OUTPUT,browserName,caseId+'-'+width+'.png'),fullPage:true});evidence.reports.push({browser:browserName,...m,violations});if(violations.length)evidence.failures.push(browserName+'/'+caseId+'/'+width+': '+violations.join(','));write();}finally{await page.close();}}}finally{await browser.close();}}if(evidence.failures.length)throw new Error(evidence.failures.join('\n'));evidence.status='PASS';write();console.log('EXPLANATION_INTEGRATION_VISUAL_PASS');}catch(error){evidence.status='FAIL';evidence.error=error.message;write();throw error;}finally{await new Promise(r=>server.close(r));}}
run().catch(error=>{console.error(error.stack||error);process.exitCode=1;});
